CREATE OR REPLACE VIEW Fix_vTot AS
SELECT
       T.Id            Tot_Id          , T.FYear           Tot_Year           , T.FMonth        Tot_Month       , T.Qnt             Tot_Qnt            ,
       T.CQnt          Tot_CQnt        , T.Price           Tot_Price          , T.Amt           Tot_Amt         , T.Perc            Tot_Perc           ,
       T.FTot          Tot_FTot        , T.FAmt            Tot_FAmt           , T.RTot          Tot_RTot        , T.RAmt            Tot_RAmt           ,
       T.Vhr_Id      ,
       I.Mst_Id      , I.Mst_Num       , I.Mst_Date      , I.Mst_Rem          , I.Period_Id   , I.Period_Name   , I.Commit_Id     , I.Commit_Name      ,
       I.Acc_Id      , I.Acc_Num       , I.Acc_Name      , I.Acc_FName        , I.Trn_Id      , I.Trn_SDate     , I.Trn_EDate     ,
       I.Trn_Qnt     , I.Trn_CQnt      , I.Trn_SQnt      , I.Trn_SCQnt        , I.Trn_Price   , I.Trn_Amt       , I.Trn_CAmt      , I.Trn_Perc         ,
       I.Trn_FTot    , I.Trn_FAmt      , I.Trn_RTot      , I.Trn_RAmt         , I.Trn_Rem     , I.Trn_Spc6      ,
       I.Fixd_Id     , I.Fixd_Num      , I.Fixd_Name     , I.Fixd_FName       , I.Fixd_Perc   , I.Fixd_Rem      ,
       I.Fixd_Spc1_Id, I.Fixd_Spc1_Name, I.Fixd_Spc2_Id  , I.Fixd_Spc2_Name   , I.Fixd_Spc3_Id, I.Fixd_Spc3_Name, I.Fixd_Spc4_Id  , I.Fixd_Spc4_Name   ,
       I.Fixd_Spc5_Id, I.Fixd_Spc5_Name, I.Fixd_Unit_Id  , I.Fixd_Unit_Name   , I.Fixd_Acc_Id , I.Fixd_Acc_Num  , I.Fixd_Acc_Name , I.Fixd_Acc_FullName,
       I.Fixd_Acc_DId, I.Fixd_Acc_DNum , I.Fixd_Acc_DName, I.Fixd_Acc_DFName  , I.Fixd_Acc_RId, I.Fixd_Acc_RNum , I.Fixd_Acc_RName, I.Fixd_Acc_RFName  ,
       I.Fixd_Acc_FId, I.Fixd_Acc_FNum , I.Fixd_Acc_FName, I.Fixd_Acc_FFName  , I.Loc1_Id     , I.Loc1_Name     , I.Loc2_Id       , I.Loc2_Name        ,
       I.Loc3_Id     , I.Loc3_Name     , I.Status_Id     , I.Status_Name      , I.Spc1_Id     , I.Spc1_Name     , I.Spc2_Id       , I.Spc2_Name        ,
       I.Spc3_Id     , I.Spc3_Name     , I.Spc4_Id       , I.Spc4_Name        ,
       I.Spc5_Id     , I.Spc5_Name
  FROM Fix_Tot     T,
       Fix_VInDocs I
 WHERE T.FTrn_Id=I.Trn_Id;

